# input — generated by tools/gen_model_py.py from the yaml
# cascade (2026-09-02 flip), then hand-edited since. The
# class IS the unit: family head → variants → quant cells;
# merged_defaults() walks the cascade. Parity pinned by
# tests/walls/suites/test_python_models.py + the http goldens.
#
# SSOT law: this file REPLACES model.yaml + variants/. A
# model.yaml reappearing next to it is a LOUD refusal.


from melite_models import  KnobRow,Model, Variant, Cell, LoraRow, Genre, ClipType, Quant


class Input(Model):
    id = 'input'
    genre = Genre.IMAGE
    label = 'Input Prep'
    # (2026-09-05: the class was generated with description='>-'
    # (a yaml-folding fossil) and defaults naming no card field —
    # both refused/purged here. The lane takes NO model-level knobs:
    # everything rides the card's `source` field + the fixed
    # InputCardEditor wire; the cross-validation law demands every
    # default name a field on the owning card.)
    description = ('Source intake: attach an image or audio file '
                   '(upload, asset drop, prior run) — staged, '
                   'optionally transformed, emitted as a media '
                   'artifact for downstream cards to wire.')
    # BOARDED 2026-09-05 (the "input cards don't accept image files"
    # incident): the lane boards the input-prep card as a comfyui
    # engine unit. Weightless means no checkpoint (the NATIVE quant
    # cell), NOT engineless — execution rides ComfyUI core load/save
    # nodes, so the family declares the engine like every boarded
    # model (resolve_model refuses engineless units: an offered model
    # must resolve).
    engine = 'comfyui'
    card = 'input-prep'       # the owning card (cross-validation hook)
    form = 'form_input'
    # INGESTION (2026-09-06 — the "Input cards don't accept image
    # files" incident, second half): the canvas drop gate reads this
    # off the served catalog. Image + audio — the card's own copy
    # ("Image or audio (video is not boarded yet)"); video refuses
    # at the lane (the estate's video rail is VHS), so a video drop
    # still toasts, correctly this time.
    accepts = ('image', 'audio')
    defaults = dict()
    # the CASCADE GATE (image-edit rework 2026-09-05) — a weightless
    # tool / transport / preprocessor lane ships NATIVE as its single
    # quant (no weights matrix; the lane's own engine owns whatever
    # load it has).
    variants = (
        Variant(id='standard', label='Standard', route='input', cells=(
            Cell(quant=Quant.NATIVE, label='Native (weightless)', route='input'),
        )),
    )

    # the input-prep card surface (row 3, 2026-09-06 — ninth card in
    # the KnobRow migration). ONE row: source is the only scalar
    # knob with a configuration-independent meaning. The row targets
    # the image-branch loader (the card's primary genre); the audio
    # branch loads LoadAudio.0.audio instead (media-gated twin,
    # stated here). crop/scale/trim/volume are nested/conditional
    # transform rows — no 1:1 inject exists (a complex-knob row
    # shape is a later stroke, the ideogram fan-out note's kin).
    card_knobs = (
        KnobRow(card='source', inject='LoadImage.0.image', kind='s'),
    )


